import java.io.*;import java.nio.file.*;import java.util.*;
public class Main {static class PassStore{Path file;PassStore(Path p){file=p;}void add(String line)throws IOException{try(BufferedWriter w=Files.newBufferedWriter(file,StandardOpenOption.CREATE,StandardOpenOption.APPEND)){w.write(line);w.newLine();}}Optional<String> find(String id)throws IOException{try(BufferedReader r=Files.newBufferedReader(file)){String s;while((s=r.readLine())!=null)if(s.startsWith(id+","))return Optional.of(s);}return Optional.empty();}}public static void main(String[]a)throws Exception{PassStore s=new PassStore(Path.of("passes.txt"));s.add("P1001,192311001,Mahesh,12");long t=System.nanoTime();System.out.println(s.find("P1001"));System.out.println("lookup(ns)="+(System.nanoTime()-t));}}
